classdef fuzzySystemLiteratureFixture < matlab.unittest.fixtures.Fixture
    % Published, non-random examples for inverse fuzzy systems.
    %
    % Sources are recorded beside each example so a failing test can be
    % checked against the original publication instead of another
    % implementation of the solver.

    properties
        MaxMin
        MinMax
    end

    methods
        function setup(fixture)
            % Z. Zahariev, "Solving Max-Min Fuzzy Linear Systems of
            % Equations. Algorithm and Software", Annual of Informatics
            % Section, Vol. 6 (2013), Section 5.1, Example 1.
            % https://old.usb-bg.org/Bg/Annual_Informatics/2013/
            % SUB-Informatics-2013-6-001-016.pdf
            %
            % The paper labels the third vector on p. 10 as Xlow1 again;
            % context shows that it is the third distinct minimal solution.
            fixture.MaxMin = struct( ...
                'source', 'Zahariev (2013), Section 5.1, Example 1', ...
                'a', fuzzyMatrix([ ...
                    0.7 0.0 0.9 0.4 0.7; ...
                    0.3 0.9 0.9 0.4 0.2; ...
                    0.6 0.1 0.0 0.8 0.5; ...
                    0.8 0.7 0.4 0.2 0.7; ...
                    0.4 0.1 0.2 0.5 0.1]), ...
                'b', fuzzyMatrix([0.9; 0.9; 0.7; 0.7; 0.5]), ...
                'greatest', fuzzyMatrix([0.7; 1.0; 1.0; 0.7; 1.0]), ...
                'minimal', fuzzyMatrix([ ...
                    0.7 0.0 0.0; ...
                    0.0 0.7 0.0; ...
                    0.9 0.9 0.9; ...
                    0.7 0.7 0.7; ...
                    0.0 0.0 0.7]) ...
            );

            % K. Peeva and Z. Zahariev, "A MATLAB Toolbox for Fuzzy
            % Relational Calculus in a Variety of Fuzzy Algebras",
            % Information 17(3), 256 (2026), Appendix A.1.
            % https://doi.org/10.3390/info17030256
            % The appendix publishes A, the coefficient vector, the direct
            % result B, and the least inverse solution returned by
            % is_lincomb. The greatest solution below follows directly from
            % the printed values and is also checked by the finite oracle.
            fixture.MinMax = struct( ...
                'source', 'Peeva and Zahariev (2026), Appendix A.1', ...
                'a', fuzzyMatrix([ ...
                    0.9649 0.9572 0.1419; ...
                    0.1576 0.4854 0.4218; ...
                    0.9706 0.8003 0.9157]), ...
                'witness', fuzzyMatrix([0.0344; 0.4387; 0.3816]), ...
                'b', fuzzyMatrix([0.3816; 0.1576; 0.8003]), ...
                'least', fuzzyMatrix([0; 0; 0.3816]), ...
                'maximal', fuzzyMatrix([0.1576; 0.8003; 0.3816]) ...
            );
        end
    end
end
